import {
  type OfflineCompletion,
  type OfflineWorkspace,
  type OutboxEntry,
} from '@corelive/desktop-contract/offline-workspace-v2'
import { describe, expect, test } from 'vitest'

import {
  selectUploads,
  uploadKind,
  waitingCompletionCount,
} from './completionUpload'
import { buildDeviceWorkspace, categoryUuid } from './deviceWorkspaceFixture'
import { effectiveCategory } from './effectiveCategory'
import { WorkspaceCommandError } from './WorkspaceCommandError'

const completedAt = Date.UTC(2026, 10, 3, 12)

/** Builds a keep at revision 1 that was never uploaded; overrides shape the case. */
function keep(
  id: string,
  overrides: Partial<OfflineCompletion> = {},
): OfflineCompletion {
  return {
    id,
    categoryId: categoryUuid(1),
    originalCategoryId: categoryUuid(1),
    title: `Kept ${id}`,
    rawText: `Kept ${id}`,
    lineId: `line-${id}`,
    lineIndex: 0,
    completedAt,
    originalCompletedAt: completedAt,
    timezone: 'Asia/Tokyo',
    revision: 1,
    undoUntil: completedAt,
    cancelled: false,
    restored: false,
    remote: null,
    clearAfter: null,
    cleared: false,
    ...overrides,
  }
}

/** The dashboard's stored copy of a keep. */
function remoteCopy(
  record: OfflineCompletion,
  revision: number,
  categoryId: string,
) {
  return {
    completionId: record.id,
    revision,
    cancelled: false,
    categoryId,
    title: record.title,
    completedAt: record.completedAt,
  }
}

/** An in-flight outbox entry that covers the given revision. */
function sentEntry(record: OfflineCompletion, revision: number): OutboxEntry {
  return {
    state: 'sent',
    operation: {
      operationId: `op-${record.id}-${revision}`,
      completionId: record.id,
      deviceId: 'device-1',
      revision,
      expectedRemoteRevision: 0,
      kind: 'create',
      categoryId: record.categoryId,
      title: record.title,
      completedAt: record.completedAt,
      originalCompletedAt: record.originalCompletedAt,
      timezone: record.timezone,
    },
  }
}

describe('uploadKind', () => {
  test('a never-uploaded keep is sent as a create so new writing reaches the dashboard', () => {
    // Arrange
    const record = keep('a')

    // Act
    const kind = uploadKind(record, [])

    // Assert
    expect(kind).toBe('create')
  })

  test('a keep cancelled before it ever reached the dashboard sends nothing', () => {
    // Arrange
    const record = keep('a', { cancelled: true, revision: 2 })

    // Act
    const kind = uploadKind(record, [])

    // Assert
    expect(kind).toBeNull()
  })

  test('a cancel is sent for an uploaded keep that was undone locally', () => {
    // Arrange
    const base = keep('a')
    const record = {
      ...base,
      cancelled: true,
      revision: 2,
      remote: remoteCopy(base, 1, base.categoryId),
    }

    // Act
    const kind = uploadKind(record, [])

    // Assert
    expect(kind).toBe('cancel')
  })

  test('a keep moved to another category is sent as relocate, a time edit as correctTime', () => {
    // Arrange
    const base = keep('a')
    const moved = {
      ...base,
      revision: 2,
      categoryId: categoryUuid(2),
      remote: remoteCopy(base, 1, categoryUuid(1)),
    }
    const retimed = {
      ...base,
      revision: 2,
      remote: remoteCopy(base, 1, categoryUuid(1)),
    }

    // Act
    const movedKind = uploadKind(moved, [])
    const retimedKind = uploadKind(retimed, [])

    // Assert
    expect(movedKind).toBe('relocate')
    expect(retimedKind).toBe('correctTime')
  })

  test('a keep whose delivery is uncertain is not re-sent before its receipt arrives', () => {
    // Arrange
    const record = keep('a')

    // Act
    const kind = uploadKind(record, [sentEntry(record, 1)])

    // Assert
    expect(kind).toBeNull()
  })

  test('an uncertain create is superseded by a cancel when the keep is undone meanwhile', () => {
    // Arrange
    const base = keep('a')
    const record = { ...base, cancelled: true, revision: 2 }

    // Act
    const kind = uploadKind(record, [sentEntry(base, 1)])

    // Assert
    expect(kind).toBe('cancel')
  })

  test('a keep the dashboard already holds at the same revision is not re-sent', () => {
    // Arrange
    const base = keep('a')
    const record = { ...base, remote: remoteCopy(base, 1, base.categoryId) }

    // Act
    const kind = uploadKind(record, [])

    // Assert
    expect(kind).toBeNull()
  })
})

describe('selectUploads', () => {
  /** A bound workspace with two categories whose server ids are 1 and 2. */
  function boundWorkspace(): OfflineWorkspace {
    return buildDeviceWorkspace({
      categoryCount: 2,
      boundAccountId: 'account-a',
    })
  }

  test('a Mac that never attached selects nothing so its keep path stays flat', () => {
    // Arrange
    const workspace = buildDeviceWorkspace({ categoryCount: 1 })
    workspace.completions['a'] = keep('a')

    // Act
    const candidates = selectUploads(workspace, new Map(), 16)

    // Assert
    expect(candidates).toEqual([])
  })

  test('cancellations are sent before creates even when the batch limit is one', () => {
    // Arrange
    const workspace = boundWorkspace()
    const uploaded = keep('cancelled')
    workspace.completions['create'] = keep('create')
    workspace.completions['cancelled'] = {
      ...uploaded,
      cancelled: true,
      revision: 2,
      remote: remoteCopy(uploaded, 1, uploaded.categoryId),
    }

    // Act
    const candidates = selectUploads(workspace, new Map(), 1)

    // Assert
    expect(
      candidates.map((candidate) => [candidate.completion.id, candidate.kind]),
    ).toEqual([['cancelled', 'cancel']])
  })

  test('a keep in a category without a dashboard id stays out of the batch', () => {
    // Arrange
    const workspace = boundWorkspace()
    workspace.completions['orphan'] = keep('orphan', {
      categoryId: categoryUuid(9),
    })

    // Act
    const candidates = selectUploads(workspace, new Map(), 16)

    // Assert
    expect(candidates).toEqual([])
  })

  // Regression: /ship Step 11 rerun (Codex adversarial) 2026-11-03 — a hold on records of a
  // category being deleted also stopped their Undo while that delete was parked.
  test('an Undo of a dashboard keep is sent even while its category delete is parked', () => {
    // Arrange
    const workspace = boundWorkspace()
    const uploaded = keep('undone')
    workspace.completions['undone'] = {
      ...uploaded,
      categoryId: categoryUuid(2),
      cancelled: true,
      revision: 3,
      remote: remoteCopy(uploaded, 1, categoryUuid(1)),
    }
    workspace.categoryOutbox[categoryUuid(800)] = {
      operation: {
        operationId: categoryUuid(800),
        type: 'delete',
        localId: categoryUuid(1),
        destinationLocalId: categoryUuid(2),
      },
      state: 'parked',
      receiptQueries: 0,
      frozenRevisions: [],
    }

    // Act
    const candidates = selectUploads(workspace, new Map(), 16)

    // Assert
    expect(candidates).toHaveLength(1)
    expect(candidates[0]).toMatchObject({
      kind: 'cancel',
      completion: { id: 'undone' },
    })
  })

  test('an archived keep is sent to the category its deleted source was merged into', () => {
    // Arrange
    const workspace = boundWorkspace()
    workspace.categoryMoves[categoryUuid(9)] = categoryUuid(2)
    const archived = keep('old', { categoryId: categoryUuid(9) })

    // Act
    const candidates = selectUploads(
      workspace,
      new Map([['old', archived]]),
      16,
    )

    // Assert
    expect(candidates).toHaveLength(1)
    expect(candidates[0]?.archived).toBe(true)
    expect(candidates[0]?.completion.categoryId).toBe(categoryUuid(2))
  })

  test('an archived record that was retired is not uploaded again', () => {
    // Arrange
    const workspace = boundWorkspace()
    workspace.retiredCompletions['old'] = {
      completedAt,
      originalCompletedAt: completedAt,
      originalCategoryId: categoryUuid(1),
      timezone: 'Asia/Tokyo',
      cancelled: false,
      revision: 1,
      remoteRevision: 0,
    }
    const archived = keep('old')

    // Act
    const candidates = selectUploads(
      workspace,
      new Map([['old', archived]]),
      16,
    )

    // Assert
    expect(candidates).toEqual([])
  })
})

describe('waitingCompletionCount', () => {
  test('counts a keep with an in-flight entry once and a derivable upload once', () => {
    // Arrange
    const inFlight = keep('in-flight')
    const fresh = keep('fresh')
    const state = {
      completions: { 'in-flight': inFlight, fresh },
      outbox: { op1: sentEntry(inFlight, 1) },
    }

    // Act
    const waiting = waitingCompletionCount(state)

    // Assert
    expect(waiting).toBe(2)
  })
})

describe('effectiveCategory', () => {
  test('follows chained merges to the surviving category', () => {
    // Arrange
    const workspace = buildDeviceWorkspace({ categoryCount: 1 })
    workspace.categoryMoves = {
      [categoryUuid(7)]: categoryUuid(8),
      [categoryUuid(8)]: categoryUuid(1),
    }

    // Act
    const resolved = effectiveCategory(workspace, categoryUuid(7))

    // Assert
    expect(resolved).toBe(categoryUuid(1))
  })

  test('a merge cycle is refused instead of looping forever on corrupted moves', () => {
    // Arrange
    const workspace = buildDeviceWorkspace({ categoryCount: 1 })
    workspace.categoryMoves = {
      [categoryUuid(7)]: categoryUuid(8),
      [categoryUuid(8)]: categoryUuid(7),
    }

    // Act
    const resolve = () => effectiveCategory(workspace, categoryUuid(7))

    // Assert
    expect(resolve).toThrow(WorkspaceCommandError)
  })
})
